(function(){
'use strict';
if(window.__SP_L8T3_VARIED_MODES_UI_20260903_V1)return;
window.__SP_L8T3_VARIED_MODES_UI_20260903_V1=true;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S=()=>window.L8S,T=()=>window.L8_THEME;
function themeNo(){return Number(T()?.number||3)}
function taskNo(task){const i=(T()?.tasks||[]).findIndex(t=>String(t?.id)===String(task?.id));return i>=0?i+1:''}
function state(task){return S().load(themeNo(),task.id,task.items.length)}
function next(task){return S().nextIndex(themeNo(),task.id,task.items.length)}
function head(task,st){const done=st.done?.length||0,pct=Math.round(done/Math.max(1,task.items.length)*100);return `<section class="l8-card sp-vm-head" data-sp-task-stage><div class="sp-vm-kicker">Aufgabe ${taskNo(task)}</div><h1>${esc(task.emoji||'✨')} ${esc(task.title)}</h1><p>${esc(task.instruction||'')}</p><div class="sp-vm-progress"><span>${done} von ${task.items.length} fertig</span><strong>${pct}%</strong></div><div class="sp-vm-bar"><span style="width:${pct}%"></span></div></section>`}
function finish(icon,text){const root=document.getElementById('app');if(root)root.innerHTML=`<div class="l8-wrap"><section class="l8-card sp-vm-finish" data-sp-task-stage><div>${icon}</div><h2>Aufgabe abgeschlossen</h2><p>${esc(text)}</p><a class="l8-btn primary" href="index.html">Zur Übersicht</a></section></div>`}
function note(st,idx){const tries=Number(st.tries?.[idx]||0);if(tries===1)return'<div class="sp-vm-note bad">Noch nicht richtig. Prüfe Verb und Form.</div>';if(tries===2)return'<div class="sp-vm-note hint">Tipp: Erst Bedeutung prüfen: sein oder haben? Danach auf das Subjekt achten.</div>';if(tries>=3)return'<div class="sp-vm-note hint">Nutze die Konjugationstabelle aus der vorherigen Aufgabe.</div>';return''}
const shuffle=values=>{const a=[...(values||[])];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function forms(family){return family==='sein'?shuffle(['war','warst','waren','wart']):shuffle(['hatte','hattest','hatten','hattet'])}
function duel(task){
 const root=document.getElementById('app');if(!root||!S())return false;let st=state(task),idx=next(task);if(idx==null||st.done.length>=task.items.length){finish('⚔️','Du hast sein/haben und die Präteritumformen richtig unterschieden.');return true}st=state(task);const item=task.items[idx];let family='',form='';
 root.innerHTML=`<div class="l8-wrap">${head(task,st)}<section class="l8-card sp-duel" data-sp-task-stage><div class="sp-duel-sentence">${esc(item.sentence||'')}</div><div class="sp-duel-step"><span>1</span><div><b>Welches Verb?</b><div class="sp-duel-buttons"><button type="button" data-family="sein">sein</button><button type="button" data-family="haben">haben</button></div></div></div><div class="sp-duel-step sp-duel-form-step" hidden><span>2</span><div><b>Welche Form passt?</b><div class="sp-duel-buttons" id="spDuelForms"></div></div></div><div class="sp-duel-actions"><button class="l8-btn primary" id="spDuelCheck" type="button" disabled>Prüfen</button></div>${note(st,idx)}</section></div>`;
 const formStep=root.querySelector('.sp-duel-form-step'),formBox=document.getElementById('spDuelForms'),check=document.getElementById('spDuelCheck');
 root.querySelectorAll('[data-family]').forEach(btn=>btn.onclick=()=>{family=btn.dataset.family||'';form='';root.querySelectorAll('[data-family]').forEach(b=>b.classList.toggle('selected',b===btn));formBox.innerHTML=forms(family).map(v=>`<button type="button" data-form="${esc(v)}">${esc(v)}</button>`).join('');formBox.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>{form=b.dataset.form||'';formBox.querySelectorAll('[data-form]').forEach(x=>x.classList.toggle('selected',x===b));check.disabled=!form});formStep.hidden=false;check.disabled=true});
 check.onclick=()=>{if(!family||!form)return;const okFamily=family===item.verb,okForm=S().equal(form,item.answer||[]),stored=family+'|||'+form;if(okFamily&&okForm){S().right(themeNo(),task.id,task.items.length,idx,stored);setTimeout(()=>duel(task),180)}else{S().wrong(themeNo(),task.id,task.items.length,idx,stored);duel(task)}};
 return true
}
function detective(task){
 const root=document.getElementById('app');if(!root||!S())return false;let st=state(task),idx=next(task);if(idx==null||st.done.length>=task.items.length){finish('🕵️','Du hast alle Aussagen den richtigen Personen zugeordnet.');return true}st=state(task);const item=task.items[idx],profiles=task.profiles||[];let active=profiles[0]?.id||'';
 const dossier=()=>{const p=profiles.find(x=>x.id===active)||profiles[0]||{};return `<div class="sp-detective-file"><div class="sp-detective-file-title">📄 ${esc(p.title||p.name||'')}</div><p>${esc(p.text||'')}</p></div>`};
 root.innerHTML=`<div class="l8-wrap">${head(task,st)}<section class="l8-card sp-detective" data-sp-task-stage><div class="sp-detective-tabs">${profiles.map((p,i)=>`<button type="button" data-profile-tab="${esc(p.id)}" class="${i===0?'active':''}">${esc(p.name)}</button>`).join('')}</div><div id="spDetectiveFile">${dossier()}</div><div class="sp-detective-case"><span>🔎 Aussage</span><strong>${esc(item.prompt||'')}</strong></div><div class="sp-detective-answers">${(item.options||profiles.map(p=>p.id)).map(id=>{const p=profiles.find(x=>x.id===id);return `<button type="button" data-person="${esc(id)}">${esc(p?.name||id)}</button>`}).join('')}</div>${Number(st.tries?.[idx]||0)>0?'<div class="sp-vm-note bad">Diese Person passt noch nicht. Lies die Texte noch einmal.</div>':''}</section></div>`;
 root.querySelectorAll('[data-profile-tab]').forEach(btn=>btn.onclick=()=>{active=btn.dataset.profileTab||'';root.querySelectorAll('[data-profile-tab]').forEach(b=>b.classList.toggle('active',b===btn));document.getElementById('spDetectiveFile').innerHTML=dossier()});
 root.querySelectorAll('[data-person]').forEach(btn=>btn.onclick=()=>{const value=btn.dataset.person||'';if(S().equal(value,item.answer||[])){S().right(themeNo(),task.id,task.items.length,idx,value);setTimeout(()=>detective(task),180)}else{S().wrong(themeNo(),task.id,task.items.length,idx,value);detective(task)}});
 return true
}
function install(){if(!window.L8UI||window.L8UI.__spT3VariedModes)return false;const raw=window.L8UI.taskPage.bind(window.L8UI);window.L8UI.taskPage=function(){const id=new URLSearchParams(location.search).get('task'),task=(T()?.tasks||[]).find(t=>String(t?.id)===String(id));if(task?.spL8T3VerbFormDuel)return duel(task);if(task?.spL8T3ReadingDetective)return detective(task);return raw()};window.L8UI.__spT3VariedModes=true;return true}
const style=document.createElement('style');style.id='sp-l8t3-varied-modes-style';style.textContent=`.sp-vm-head h1{margin:6px 0 8px}.sp-vm-kicker{font-weight:900;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}.sp-vm-progress{display:flex;justify-content:space-between;gap:12px;margin-top:14px;font-weight:850}.sp-vm-bar{height:9px;border-radius:999px;background:#ececf2;overflow:hidden;margin-top:6px}.sp-vm-bar span{display:block;height:100%;background:var(--lesson-main,var(--l8-main,#68539b))}.sp-vm-finish{text-align:center}.sp-vm-finish>div:first-child{font-size:54px}.sp-vm-note{margin-top:14px;padding:10px 12px;border-radius:12px;font-weight:800}.sp-vm-note.bad{background:#fff0f0;color:#9d2828}.sp-vm-note.hint{background:#fff8dc;color:#725500}.sp-duel{display:grid;gap:18px}.sp-duel-sentence{font-size:25px;font-weight:900;text-align:center;padding:20px;border-radius:16px;background:var(--lesson-soft,var(--l8-soft,#f3effa))}.sp-duel-step{display:grid;grid-template-columns:44px 1fr;gap:12px;align-items:start}.sp-duel-step>span{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:var(--lesson-main,var(--l8-main));color:#fff;font-weight:950}.sp-duel-step b{display:block;margin:7px 0 10px;font-size:18px}.sp-duel-buttons{display:flex;flex-wrap:wrap;gap:9px}.sp-duel-buttons button,.sp-detective-tabs button,.sp-detective-answers button{border:2px solid var(--lesson-line,var(--l8-line,#ddd));background:#fff;border-radius:12px;padding:10px 16px;font:inherit;font-weight:850;cursor:pointer}.sp-duel-buttons button.selected,.sp-detective-tabs button.active{border-color:var(--lesson-main,var(--l8-main));background:var(--lesson-soft,var(--l8-soft,#f3effa))}.sp-duel-actions{text-align:center}.sp-detective{display:grid;gap:16px}.sp-detective-tabs{display:flex;gap:8px;flex-wrap:wrap}.sp-detective-file{padding:16px;border-radius:15px;background:#f7f8fb;border:1px solid var(--lesson-line,var(--l8-line,#ddd));line-height:1.55}.sp-detective-file-title{font-weight:950;margin-bottom:8px}.sp-detective-file p{margin:0}.sp-detective-case{padding:16px;border:2px dashed var(--lesson-main,var(--l8-main));border-radius:15px;background:#fff}.sp-detective-case span{display:block;font-size:12px;text-transform:uppercase;font-weight:900;color:var(--muted);margin-bottom:6px}.sp-detective-case strong{font-size:20px;line-height:1.4}.sp-detective-answers{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.sp-detective-answers button:hover{border-color:var(--lesson-main,var(--l8-main))}@media(max-width:720px){.sp-detective-answers{grid-template-columns:repeat(2,minmax(0,1fr))}.sp-duel-sentence{font-size:21px}.sp-duel-step{grid-template-columns:36px 1fr}.sp-duel-step>span{width:32px;height:32px}}`;
document.head.appendChild(style);
window.L8T3VariedModesUI20260903={install,duel,detective,version:1};
})();
